export interface Performance {
  readonly id: string;
  readonly venueId: string;
}

export interface ReservationDraft {
  readonly id?: string;
  readonly customerId: string;
  readonly performanceId: string;
  readonly seat: string;
}

export interface Reservation {
  readonly id: string;
  readonly customerId: string;
  readonly performanceId: string;
  readonly seat: string;
}

type ReservationPatch = Partial<Omit<ReservationDraft, "id">>;

function nonempty(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

export class ReservationStore {
  private readonly performances = new Map<string, Performance>();
  private readonly reservations = new Map<string, Reservation>();
  private nextId = 1;

  constructor(performances: readonly Performance[]) {
    for (const item of performances) {
      if (!item || !nonempty(item.id) || !nonempty(item.venueId) || this.performances.has(item.id)) {
        throw new TypeError("Invalid or duplicate performance");
      }
      this.performances.set(item.id, { id: item.id, venueId: item.venueId });
    }
  }

  add(draft: ReservationDraft): Reservation {
    this.validate(draft);
    let id = draft.id;
    if (id !== undefined && this.reservations.has(id)) {
      throw new RangeError("Duplicate reservation ID");
    }
    if (id === undefined) {
      do {
        id = `reservation-${this.nextId++}`;
      } while (this.reservations.has(id));
    }
    const value: Reservation = {
      id,
      customerId: draft.customerId,
      performanceId: draft.performanceId,
      seat: draft.seat
    };
    this.reservations.set(id, value);
    return { ...value };
  }

  get(id: string): Reservation | null {
    const value = this.reservations.get(id);
    return value ? { ...value } : null;
  }

  byCustomer(customerId: string): Reservation[] {
    return [...this.reservations.values()]
      .filter((value) => value.customerId === customerId)
      .map((value) => ({ ...value }));
  }

  byPerformance(performanceId: string): Reservation[] {
    return [...this.reservations.values()]
      .filter((value) => value.performanceId === performanceId)
      .map((value) => ({ ...value }));
  }

  update(id: string, patch: ReservationPatch): Reservation | null {
    const current = this.reservations.get(id);
    if (!current) return null;

    const candidate: Reservation = {
      id: current.id,
      customerId: patch.customerId === undefined ? current.customerId : patch.customerId,
      performanceId: patch.performanceId === undefined ? current.performanceId : patch.performanceId,
      seat: patch.seat === undefined ? current.seat : patch.seat
    };
    this.validate(candidate);
    this.reservations.set(id, candidate);
    return { ...candidate };
  }

  delete(id: string): boolean {
    return this.reservations.delete(id);
  }

  private validate(value: ReservationDraft): void {
    if (!value || !nonempty(value.customerId) || !nonempty(value.performanceId) || !nonempty(value.seat) ||
        (value.id !== undefined && !nonempty(value.id))) {
      throw new TypeError("Invalid reservation");
    }
    if (!this.performances.has(value.performanceId)) {
      throw new RangeError("Unknown performance");
    }
  }
}
